-- GENERATED by `make gen` from stats/registry -- edit the registry, not this file.
-- The daily stat rollup (POKER_PLAN.md §2.3, ADR-021): every group key is in the ORDER
-- BY, one opportunity / action pair per `cached` stat. Decision-grain stats are counted
-- on `decisions`, hand-grain on `player_hands`; the two branches zero-fill each other's
-- columns and SummingMergeTree adds rows sharing a key, so `sum(x)` is exact before and
-- after merges. Adding a stat is one registry entry and `make gen`.

{{
  config(
    materialized='incremental',
    incremental_strategy='insert_overwrite',
    engine='SummingMergeTree()',
    order_by='(user_id, dataset, player_key, day, site, stake_level, game_type, table_format, position, is_hero, is_anonymized)',
    partition_by='toYYYYMMDD(day)',
  )
}}

select
    user_id,
    dataset,
    player_key_norm as player_key,
    played_date as day,
    site,
    stake_level,
    game_type,
    table_format,
    position,
    is_hero,
    is_anonymized,
    toUInt64(0) as hands,
    toUInt64(0) as bb_per_100_opp,
    toDecimal128(0, 4) as bb_per_100_action,
    toUInt64(0) as ev_bb_per_100_opp,
    toDecimal128(0, 4) as ev_bb_per_100_action,
    toUInt64(0) as sd_bb_per_100_opp,
    toDecimal128(0, 4) as sd_bb_per_100_action,
    toUInt64(0) as nsd_bb_per_100_opp,
    toDecimal128(0, 4) as nsd_bb_per_100_action,
    countIf(street = 'flop' AND am_preflop_aggressor = 1 AND facing = 'none') as cbet_flop_opp,
    countIf(street = 'flop' AND am_preflop_aggressor = 1 AND facing = 'none' AND action = 'bet') as cbet_flop_action,
    countIf(street = 'turn' AND am_preflop_aggressor = 1 AND am_prev_street_aggressor = 1 AND facing = 'none') as cbet_turn_opp,
    countIf(street = 'turn' AND am_preflop_aggressor = 1 AND am_prev_street_aggressor = 1 AND facing = 'none' AND action = 'bet') as cbet_turn_action,
    countIf(street = 'river' AND am_preflop_aggressor = 1 AND am_prev_street_aggressor = 1 AND facing = 'none') as cbet_river_opp,
    countIf(street = 'river' AND am_preflop_aggressor = 1 AND am_prev_street_aggressor = 1 AND facing = 'none' AND action = 'bet') as cbet_river_action,
    countIf(street = 'turn' AND am_preflop_aggressor = 1 AND prev_street_my_action = 'x' AND facing = 'none') as delayed_cbet_opp,
    countIf(street = 'turn' AND am_preflop_aggressor = 1 AND prev_street_my_action = 'x' AND facing = 'none' AND action = 'bet') as delayed_cbet_action,
    countIf(street = 'flop' AND facing = 'bet' AND facing_is_cbet = 1) as fold_to_cbet_flop_opp,
    countIf(street = 'flop' AND facing = 'bet' AND facing_is_cbet = 1 AND action = 'fold') as fold_to_cbet_flop_action,
    countIf(street = 'flop' AND facing = 'bet' AND facing_is_cbet = 1) as call_cbet_flop_opp,
    countIf(street = 'flop' AND facing = 'bet' AND facing_is_cbet = 1 AND action = 'call') as call_cbet_flop_action,
    countIf(street = 'flop' AND facing = 'bet' AND facing_is_cbet = 1) as raise_cbet_flop_opp,
    countIf(street = 'flop' AND facing = 'bet' AND facing_is_cbet = 1 AND action = 'raise') as raise_cbet_flop_action,
    countIf(street = 'turn' AND facing = 'bet' AND facing_is_cbet = 1) as fold_to_cbet_turn_opp,
    countIf(street = 'turn' AND facing = 'bet' AND facing_is_cbet = 1 AND action = 'fold') as fold_to_cbet_turn_action,
    countIf(street = 'river' AND facing = 'bet' AND facing_is_cbet = 1) as fold_to_cbet_river_opp,
    countIf(street = 'river' AND facing = 'bet' AND facing_is_cbet = 1 AND action = 'fold') as fold_to_cbet_river_action,
    countIf(street = 'turn' AND am_preflop_aggressor = 0 AND prev_street_my_action = 'x' AND prev_street_faced = 'none' AND facing = 'bet' AND facing_is_cbet = 1) as fold_to_delayed_cbet_opp,
    countIf(street = 'turn' AND am_preflop_aggressor = 0 AND prev_street_my_action = 'x' AND prev_street_faced = 'none' AND facing = 'bet' AND facing_is_cbet = 1 AND action = 'fold') as fold_to_delayed_cbet_action,
    countIf(street = 'turn' AND am_preflop_aggressor = 0 AND is_ip = 1 AND prev_street_faced = 'bet' AND prev_street_my_action = 'c' AND facing = 'none') as float_flop_opp,
    countIf(street = 'turn' AND am_preflop_aggressor = 0 AND is_ip = 1 AND prev_street_faced = 'bet' AND prev_street_my_action = 'c' AND facing = 'none' AND action = 'bet') as float_flop_action,
    countIf(street = 'turn' AND am_preflop_aggressor = 0 AND is_ip = 1 AND prev_street_faced = 'bet' AND prev_street_my_action = 'c' AND facing = 'bet') as float_fold_opp,
    countIf(street = 'turn' AND am_preflop_aggressor = 0 AND is_ip = 1 AND prev_street_faced = 'bet' AND prev_street_my_action = 'c' AND facing = 'bet' AND action = 'fold') as float_fold_action,
    countIf(street = 'flop' AND am_preflop_aggressor = 0 AND is_ip = 0 AND facing = 'none') as donk_flop_opp,
    countIf(street = 'flop' AND am_preflop_aggressor = 0 AND is_ip = 0 AND facing = 'none' AND action = 'bet') as donk_flop_action,
    countIf(street = 'flop' AND am_preflop_aggressor = 1 AND facing = 'bet') as fold_to_donk_opp,
    countIf(street = 'flop' AND am_preflop_aggressor = 1 AND facing = 'bet' AND action = 'fold') as fold_to_donk_action,
    countIf(street = 'turn' AND am_preflop_aggressor = 0 AND is_ip = 0 AND prev_street_my_action = 'x' AND prev_street_faced = 'none' AND facing = 'none') as probe_turn_opp,
    countIf(street = 'turn' AND am_preflop_aggressor = 0 AND is_ip = 0 AND prev_street_my_action = 'x' AND prev_street_faced = 'none' AND facing = 'none' AND action = 'bet') as probe_turn_action,
    countIf(street = 'turn' AND am_preflop_aggressor = 1 AND prev_street_my_action = 'x' AND prev_street_faced = 'none' AND facing = 'bet') as fold_to_probe_turn_opp,
    countIf(street = 'turn' AND am_preflop_aggressor = 1 AND prev_street_my_action = 'x' AND prev_street_faced = 'none' AND facing = 'bet' AND action = 'fold') as fold_to_probe_turn_action,
    countIf(street = 'river' AND am_preflop_aggressor = 0 AND is_ip = 0 AND prev_street_my_action = 'x' AND prev_street_faced = 'none' AND facing = 'none') as probe_river_opp,
    countIf(street = 'river' AND am_preflop_aggressor = 0 AND is_ip = 0 AND prev_street_my_action = 'x' AND prev_street_faced = 'none' AND facing = 'none' AND action = 'bet') as probe_river_action,
    countIf(street = 'river' AND am_preflop_aggressor = 1 AND prev_street_my_action = 'x' AND prev_street_faced = 'none' AND facing = 'bet') as fold_to_probe_river_opp,
    countIf(street = 'river' AND am_preflop_aggressor = 1 AND prev_street_my_action = 'x' AND prev_street_faced = 'none' AND facing = 'bet' AND action = 'fold') as fold_to_probe_river_action,
    countIf(street = 'flop' AND street_line = 'x' AND facing = 'bet') as check_raise_flop_opp,
    countIf(street = 'flop' AND street_line = 'x' AND facing = 'bet' AND action = 'raise') as check_raise_flop_action,
    countIf(street = 'turn' AND street_line = 'x' AND facing = 'bet') as check_raise_turn_opp,
    countIf(street = 'turn' AND street_line = 'x' AND facing = 'bet' AND action = 'raise') as check_raise_turn_action,
    countIf(street = 'river' AND street_line = 'x' AND facing = 'bet') as check_raise_river_opp,
    countIf(street = 'river' AND street_line = 'x' AND facing = 'bet' AND action = 'raise') as check_raise_river_action,
    countIf(street = 'flop' AND street_line = 'b' AND facing = 'raise') as fold_to_flop_raise_opp,
    countIf(street = 'flop' AND street_line = 'b' AND facing = 'raise' AND action = 'fold') as fold_to_flop_raise_action,
    countIf(street = 'turn' AND street_line = 'b' AND facing = 'raise') as fold_to_turn_raise_opp,
    countIf(street = 'turn' AND street_line = 'b' AND facing = 'raise' AND action = 'fold') as fold_to_turn_raise_action,
    countIf(street = 'river' AND street_line = 'b' AND facing = 'raise') as fold_to_river_raise_opp,
    countIf(street = 'river' AND street_line = 'b' AND facing = 'raise' AND action = 'fold') as fold_to_river_raise_action,
    countIf(street = 'river' AND street_line = 'b' AND facing = 'raise') as bet_call_river_opp,
    countIf(street = 'river' AND street_line = 'b' AND facing = 'raise' AND action = 'call') as bet_call_river_action,
    countIf(street = 'river' AND facing = 'bet') as river_raise_opp,
    countIf(street = 'river' AND facing = 'bet' AND action = 'raise') as river_raise_action,
    countIf(street = 'river' AND street_line = 'x' AND facing = 'bet') as river_check_fold_opp,
    countIf(street = 'river' AND street_line = 'x' AND facing = 'bet' AND action = 'fold') as river_check_fold_action,
    countIf(street = 'river' AND street_line = 'x' AND facing = 'bet') as river_check_call_opp,
    countIf(street = 'river' AND street_line = 'x' AND facing = 'bet' AND action = 'call') as river_check_call_action,
    toUInt64(0) as vpip_opp,
    toUInt64(0) as vpip_action,
    toUInt64(0) as pfr_opp,
    toUInt64(0) as pfr_action,
    countIf(street = 'preflop' AND facing = 'none') as rfi_opp,
    countIf(street = 'preflop' AND facing = 'none' AND action = 'raise') as rfi_action,
    countIf(street = 'preflop' AND facing = 'none' AND position IN ('CO', 'BTN', 'SB')) as steal_opp,
    countIf(street = 'preflop' AND facing = 'none' AND position IN ('CO', 'BTN', 'SB') AND action = 'raise') as steal_action,
    countIf(street = 'preflop' AND facing = 'none' AND position != 'BB') as limp_opp,
    countIf(street = 'preflop' AND facing = 'none' AND position != 'BB' AND action = 'call') as limp_action,
    countIf(street = 'preflop' AND facing = 'limp') as iso_raise_opp,
    countIf(street = 'preflop' AND facing = 'limp' AND action = 'raise') as iso_raise_action,
    countIf(street = 'preflop' AND facing IN ('raise', '3bet', '4bet', '5bet_plus') AND position NOT IN ('SB', 'BB') AND preflop_line = '') as cold_call_opp,
    countIf(street = 'preflop' AND facing IN ('raise', '3bet', '4bet', '5bet_plus') AND position NOT IN ('SB', 'BB') AND preflop_line = '' AND action = 'call') as cold_call_action,
    countIf(street = 'preflop' AND facing = 'raise') as defend_vs_open_opp,
    countIf(street = 'preflop' AND facing = 'raise' AND action = 'call') as defend_vs_open_action,
    countIf(street = 'preflop' AND facing = 'raise') as fold_vs_open_opp,
    countIf(street = 'preflop' AND facing = 'raise' AND action = 'fold') as fold_vs_open_action,
    countIf(street = 'preflop' AND facing = 'raise') as threebet_opp,
    countIf(street = 'preflop' AND facing = 'raise' AND action = 'raise') as threebet_action,
    countIf(street = 'preflop' AND facing = 'raise' AND n_cold_callers >= 1) as squeeze_opp,
    countIf(street = 'preflop' AND facing = 'raise' AND n_cold_callers >= 1 AND action = 'raise') as squeeze_action,
    countIf(street = 'preflop' AND facing = '3bet' AND am_preflop_opener = 1) as fold_to_3bet_opp,
    countIf(street = 'preflop' AND facing = '3bet' AND am_preflop_opener = 1 AND action = 'fold') as fold_to_3bet_action,
    countIf(street = 'preflop' AND facing = '3bet' AND am_preflop_opener = 1) as call_3bet_opp,
    countIf(street = 'preflop' AND facing = '3bet' AND am_preflop_opener = 1 AND action = 'call') as call_3bet_action,
    countIf(street = 'preflop' AND facing = '3bet') as fourbet_opp,
    countIf(street = 'preflop' AND facing = '3bet' AND action = 'raise') as fourbet_action,
    countIf(street = 'preflop' AND facing = '4bet' AND am_preflop_opener = 0 AND preflop_line = 'r') as fold_to_4bet_opp,
    countIf(street = 'preflop' AND facing = '4bet' AND am_preflop_opener = 0 AND preflop_line = 'r' AND action = 'fold') as fold_to_4bet_action,
    countIf(street = 'preflop' AND facing = '4bet' AND am_preflop_opener = 0 AND preflop_line = 'r') as call_4bet_opp,
    countIf(street = 'preflop' AND facing = '4bet' AND am_preflop_opener = 0 AND preflop_line = 'r' AND action = 'call') as call_4bet_action,
    countIf(street = 'preflop' AND facing = '4bet') as fivebet_opp,
    countIf(street = 'preflop' AND facing = '4bet' AND action = 'raise') as fivebet_action,
    countIf(street = 'preflop' AND position = 'BB' AND facing = 'raise' AND opener_position IN ('CO', 'BTN', 'SB') AND n_limpers = 0) as fold_bb_to_steal_opp,
    countIf(street = 'preflop' AND position = 'BB' AND facing = 'raise' AND opener_position IN ('CO', 'BTN', 'SB') AND n_limpers = 0 AND action = 'fold') as fold_bb_to_steal_action,
    countIf(street = 'preflop' AND preflop_line = 'l' AND facing IN ('raise', '3bet', '4bet', '5bet_plus')) as limp_fold_opp,
    countIf(street = 'preflop' AND preflop_line = 'l' AND facing IN ('raise', '3bet', '4bet', '5bet_plus') AND action = 'fold') as limp_fold_action,
    countIf(street = 'preflop' AND preflop_line = 'l' AND facing IN ('raise', '3bet', '4bet', '5bet_plus')) as limp_call_opp,
    countIf(street = 'preflop' AND preflop_line = 'l' AND facing IN ('raise', '3bet', '4bet', '5bet_plus') AND action = 'call') as limp_call_action,
    countIf(street = 'preflop' AND preflop_line = 'l' AND facing IN ('raise', '3bet', '4bet', '5bet_plus')) as limp_raise_opp,
    countIf(street = 'preflop' AND preflop_line = 'l' AND facing IN ('raise', '3bet', '4bet', '5bet_plus') AND action = 'raise') as limp_raise_action,
    toUInt64(0) as wwsf_opp,
    toUInt64(0) as wwsf_action,
    toUInt64(0) as wtsd_opp,
    toUInt64(0) as wtsd_action,
    toUInt64(0) as wsd_opp,
    toUInt64(0) as wsd_action,
    max(src_parsed_at) as src_parsed_at
from {{ ref('decisions') }}
where {{ dirty_partitions('played_at_utc') }} and built_by = 'dbt'
group by user_id, dataset, player_key, day, site, stake_level, game_type, table_format, position, is_hero, is_anonymized

union all

select
    user_id,
    dataset,
    player_key_norm as player_key,
    played_date as day,
    site,
    stake_level,
    game_type,
    table_format,
    position,
    is_hero,
    is_anonymized,
    count() as hands,
    count() as bb_per_100_opp,
    sum(toDecimal128(net_won_bb, 4)) as bb_per_100_action,
    count() as ev_bb_per_100_opp,
    sum(toDecimal128(ev_won_bb, 4)) as ev_bb_per_100_action,
    count() as sd_bb_per_100_opp,
    sum(toDecimal128(showdown_won_bb, 4)) as sd_bb_per_100_action,
    count() as nsd_bb_per_100_opp,
    sum(toDecimal128(nonshowdown_won_bb, 4)) as nsd_bb_per_100_action,
    toUInt64(0) as cbet_flop_opp,
