    toUInt64(0) as cbet_turn_opp,
    toUInt64(0) as cbet_turn_action,
    toUInt64(0) as cbet_river_opp,
    toUInt64(0) as cbet_river_action,
    toUInt64(0) as delayed_cbet_opp,
    toUInt64(0) as delayed_cbet_action,
    toUInt64(0) as fold_to_cbet_flop_opp,
    toUInt64(0) as fold_to_cbet_flop_action,
    toUInt64(0) as call_cbet_flop_opp,
    toUInt64(0) as call_cbet_flop_action,
    toUInt64(0) as raise_cbet_flop_opp,
    toUInt64(0) as raise_cbet_flop_action,
    toUInt64(0) as fold_to_cbet_turn_opp,
    toUInt64(0) as fold_to_cbet_turn_action,
    toUInt64(0) as fold_to_cbet_river_opp,
    toUInt64(0) as fold_to_cbet_river_action,
    toUInt64(0) as fold_to_delayed_cbet_opp,
    toUInt64(0) as fold_to_delayed_cbet_action,
    toUInt64(0) as float_flop_opp,
    toUInt64(0) as float_flop_action,
    toUInt64(0) as float_fold_opp,
    toUInt64(0) as float_fold_action,
    toUInt64(0) as donk_flop_opp,
    toUInt64(0) as donk_flop_action,
    toUInt64(0) as fold_to_donk_opp,
    toUInt64(0) as fold_to_donk_action,
    toUInt64(0) as probe_turn_opp,
    toUInt64(0) as probe_turn_action,
    toUInt64(0) as fold_to_probe_turn_opp,
    toUInt64(0) as fold_to_probe_turn_action,
    toUInt64(0) as probe_river_opp,
    toUInt64(0) as probe_river_action,
    toUInt64(0) as fold_to_probe_river_opp,
    toUInt64(0) as fold_to_probe_river_action,
    toUInt64(0) as check_raise_flop_opp,
    toUInt64(0) as check_raise_flop_action,
    toUInt64(0) as check_raise_turn_opp,
    toUInt64(0) as check_raise_turn_action,
    toUInt64(0) as check_raise_river_opp,
    toUInt64(0) as check_raise_river_action,
    toUInt64(0) as fold_to_flop_raise_opp,
    toUInt64(0) as fold_to_flop_raise_action,
    toUInt64(0) as fold_to_turn_raise_opp,
    toUInt64(0) as fold_to_turn_raise_action,
    toUInt64(0) as fold_to_river_raise_opp,
    toUInt64(0) as fold_to_river_raise_action,
    toUInt64(0) as bet_call_river_opp,
    toUInt64(0) as bet_call_river_action,
    toUInt64(0) as river_raise_opp,
    toUInt64(0) as river_raise_action,
    toUInt64(0) as river_check_fold_opp,
    toUInt64(0) as river_check_fold_action,
    toUInt64(0) as river_check_call_opp,
