    toUInt64(0) as cold_call_action,
    toUInt64(0) as defend_vs_open_opp,
    toUInt64(0) as defend_vs_open_action,
    toUInt64(0) as fold_vs_open_opp,
    toUInt64(0) as fold_vs_open_action,
    toUInt64(0) as threebet_opp,
    toUInt64(0) as threebet_action,
    toUInt64(0) as squeeze_opp,
    toUInt64(0) as squeeze_action,
    toUInt64(0) as fold_to_3bet_opp,
